tool_input.command:
node --input-type=module -e "
import { handle } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
const r = handle({ method:'POST', path:'/reminders', body:{ userId:'u1', text:'a', at:'2026-03-01T09:00', tzOffsetMin:330 }}).body;
console.log('IST 09:00 due UTC', new Date(r.due_ms).toISOString(), 'fires at/after 22:00Z?', dueReminders([r], Date.parse('2026-02-28T22:00:00Z')).length);
const bad = handle({ method:'POST', path:'/reminders', body:{ userId:'u1', text:'b', at:'2026-03-01T09:00:00' }}).body;
console.log('with seconds ->', bad.status ?? 201, bad.due_ms);
handle({ method:'POST', path:'/reminders', body:{ userId:'u2', text:'secret', at:'2026-03-01T09:00' }});
console.log('search apostrophe:', handle({ method:'GET', path:'/reminders/search', query:{ userId:'u1', q:\"mum's\" }}).body);
try { handle({ method:'GET', path:'/reminders' }) } catch(e) { console.log('list w/o query:', e.message) }
console.log('search no q:', handle({ method:'GET', path:'/reminders/search', query:{ userId:'u1' }}).body.length);
"
